-- ST-13b, generated by drizzle-kit and fixed by hand in two places (it is the
-- project's first table rebuild): every exam before this one came from Claude
-- Code, so the copy writes 'claude' (drizzle-kit selected a `source` column the
-- old table doesn't have); and D1 ignores `PRAGMA foreign_keys` inside a
-- migration, so the checks are deferred to commit instead. learn_exam's own
-- triggers go with the old table: 0016 recreates them.
CREATE TABLE `learn_exam_paper` (
	`exam_id` text PRIMARY KEY NOT NULL,
	`title` text NOT NULL,
	`settings_json` text NOT NULL,
	`questions_json` text NOT NULL,
	`key_json` text NOT NULL,
	`draft_json` text NOT NULL,
	`submitted_at` text,
	`results_json` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`exam_id`) REFERENCES `learn_exam`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "learn_exam_paper_json" CHECK(json_valid("learn_exam_paper"."settings_json") AND json_valid("learn_exam_paper"."questions_json") AND json_valid("learn_exam_paper"."key_json") AND json_valid("learn_exam_paper"."draft_json")),
	CONSTRAINT "learn_exam_paper_title" CHECK(length(trim("learn_exam_paper"."title")) > 0)
);
--> statement-breakpoint
PRAGMA defer_foreign_keys = on;--> statement-breakpoint
CREATE TABLE `__new_learn_exam` (
	`id` text PRIMARY KEY NOT NULL,
	`topic_id` text NOT NULL,
	`level` text NOT NULL,
	`attempt` integer NOT NULL,
	`md_path` text NOT NULL,
	`pdf_path` text,
	`source` text DEFAULT 'claude' NOT NULL,
	`created_at` text NOT NULL,
	`grade` integer,
	`graded_at` text,
	FOREIGN KEY (`topic_id`) REFERENCES `learn_topic`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "learn_exam_attempt_min" CHECK(typeof("__new_learn_exam"."attempt") = 'integer' AND "__new_learn_exam"."attempt" >= 1),
	CONSTRAINT "learn_exam_path_layout" CHECK("__new_learn_exam"."md_path" GLOB 'Study Lab/*.md'),
	CONSTRAINT "learn_exam_source_allowed" CHECK("__new_learn_exam"."source" IN ('claude', 'app')),
	CONSTRAINT "learn_exam_level_allowed" CHECK("__new_learn_exam"."level" IN ('fast_track', 'essential', 'specialized'))
);
